/**
 * The app-model-derived browser journey (quality/appJourney.ts) on the Clean Cart slice's recorded app (eval 1): as
 * generated, it fails where the person saw it fail (the Search screen was a placeholder; each PRD product was listed
 * twice); regenerated by FlowCode from the same recorded model with record identity and explicit screen aliases, it
 * passes: every PRD screen opens from the top bar, each PRD product is found once, opens, saves into Saved, and a
 * search for nothing says so. Needs the recorded workspace (its node_modules) and a browser.
 */
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { spawn, type ChildProcess } from "node:child_process";
import { afterAll, describe, expect, it } from "vitest";
import { chromium, type Browser } from "playwright";
import { journeyPlan, runJourney } from "../src/quality/appJourney.js";
import { prdNamedRecords, prdSampleSection, resolveScreenAliases, type AppModel } from "../src/orchestrator/appModel.js";
import { declaredScreens } from "../src/orchestrator/screenPlan.js";
import { mergeRecords, prdFixtureRows } from "../src/orchestrator/recordIdentity.js";
import { appFiles } from "../src/orchestrator/appFiles.js";

const REPO = path.resolve(import.meta.dirname, "../../..");
const RECORDED = path.join(REPO, ".flowcode-data/workspaces/clean-cart-slice-eval-1-9b1947");
const PRD = fs.readFileSync(path.join(REPO, "docs/handoff/slice/clean-cart-slice-prd.md"), "utf8");
const MODEL = JSON.parse(fs.readFileSync(path.join(import.meta.dirname, "fixtures/apps/eval1-app-model.json"), "utf8")) as AppModel;
const SCREENS = declaredScreens(PRD);
const NAMED = prdNamedRecords(prdSampleSection(PRD));

/** A copy of the recorded app (node_modules linked, not copied), optionally with files replaced. */
function copyApp(files: Array<{ path: string; content: string }> = []): string {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "fc-journey-"));
  const walk = (from: string, to: string) => {
    for (const e of fs.readdirSync(from, { withFileTypes: true })) {
      if (["node_modules", "dist", ".git"].includes(e.name)) continue;
      const s = path.join(from, e.name);
      const d = path.join(to, e.name);
      if (e.isDirectory()) (fs.mkdirSync(d, { recursive: true }), walk(s, d));
      else fs.copyFileSync(s, d);
    }
  };
  walk(RECORDED, root);
  fs.symlinkSync(path.join(RECORDED, "node_modules"), path.join(root, "node_modules"), "junction");
  for (const f of files) (fs.mkdirSync(path.dirname(path.join(root, f.path)), { recursive: true }), fs.writeFileSync(path.join(root, f.path), f.content));
  return root;
}

const servers: ChildProcess[] = [];
let browser: Browser | undefined;
async function serve(root: string, port: number): Promise<string> {
  const p = spawn(process.execPath, [path.join(root, "node_modules/vite/bin/vite.js"), "--port", String(port), "--strictPort", "--host", "127.0.0.1"], { cwd: root, stdio: ["ignore", "pipe", "pipe"] });
  servers.push(p);
  const url = `http://127.0.0.1:${port}/`;
  for (let i = 0; i < 120; i++) {
    if (await fetch(url).then((r) => r.ok, () => false)) return url;
    await new Promise((r) => setTimeout(r, 500));
  }
  throw new Error("vite didn't start");
}
async function journey(model: AppModel, root: string, port: number) {
  const url = await serve(root, port);
  browser ??= await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1280, height: 860 } });
  const res = await runJourney(page, url, journeyPlan(model, SCREENS, NAMED));
  await page.close();
  return res;
}
afterAll(async () => {
  await browser?.close();
  for (const p of servers) p.kill();
});

describe.skipIf(process.env.FLOWCODE_SKIP_BROWSER === "1" || !fs.existsSync(path.join(RECORDED, "node_modules")))("the functional journey on the Clean Cart slice's app", () => {
  it("fails the recorded app where it was broken: Search is a placeholder, PRD products are listed twice", async () => {
    const res = await journey(MODEL, copyApp(), 5341);
    const failed = res.steps.filter((s) => !s.ok).map((s) => `${s.step}: ${s.detail}`);
    expect(res.ok).toBe(false);
    expect(failed).toContain("Search: opens from the top bar: no working page is this screen (a placeholder doesn't count)");
    expect(failed).toContain('Search finds "Oat Milk Original": "Oat Milk Original" is shown 2 times (it is one record)');
    // What did work, kept: Home, Product and Saved open; a search for nothing says so.
    expect(res.steps.find((s) => s.step === "Saved: opens from the top bar")?.ok).toBe(true);
    expect(res.steps.find((s) => s.step === "A search that matches nothing says so")?.ok).toBe(true);
  }, 180_000);

  it("passes the same recorded model regenerated with record identity and an explicit Search alias", async () => {
    const prdRows = (e: AppModel["entities"][number]) => prdFixtureRows(e, prdSampleSection(PRD));
    const seed = Object.fromEntries(MODEL.entities.map((e) => [e.key, mergeRecords(e, [], MODEL.seed[e.key] ?? [], { prdRows: prdRows(e) }).rows]));
    const fixed = resolveScreenAliases({ ...MODEL, seed }, SCREENS);
    expect(fixed.aliases).toEqual([{ screen: "Search", view: "catalog", kind: "catalog", replaced: "search" }]);
    // Each of the PRD's products once (the recorded seed had each twice); invented ones of other brands stay separate.
    expect(NAMED.map((n) => seed.product!.filter((r) => r.name === n).length)).toEqual(NAMED.map(() => 1));
    const res = await journey(fixed, copyApp(appFiles(fixed).filter((f) => !f.path.startsWith("src/screens/"))), 5342);
    expect(res.steps.filter((s) => !s.ok)).toEqual([]);
    expect(res.steps.map((s) => s.step)).toEqual([
      "Product: opens from a record",
      "Home: opens from the top bar",
      "Search: opens from the top bar",
      "Saved: opens from the top bar",
      ...NAMED.map((n) => `Search finds "${n}"`),
      'Opening "Oat Milk Original" shows that record',
      "A visitor's Save asks them to sign in",
      "Signing in is one tap",
      'Saving "Oat Milk Original" puts the same record (Oat Milk Original, Willow Farms) in Saved',
      '"Oat Milk Original" is still in Saved after a reload',
      "A search that matches nothing says so",
    ]);
  }, 180_000);
});
